/* v4: shared cohorts, source-first reading and a reviewable quality register. */
const QUALITY_MAP=new Map(window.QUALITY.questions.map(q=>[q.id,q]));
const questionContext={topic:null,field:'topic_family',difficulty:false,label:''};
let issueFilter='all',topicField='topic_family';
function selectedQuestionRows(){return scope().filter(x=>(!questionContext.difficulty||(!difficultyState.excludeMTA||x.scoring_status!=='marks_to_all')&&(difficultyState.confidence!=='high'||x.toughness?.confidence==='high'))&&(!questionContext.topic||x[questionContext.field]===questionContext.topic)&&(difficultyQuestionBand==='all'||toughBand(x.toughness.score)===difficultyQuestionBand)&&(verdict==='all'||verdict==='changed'&&x.subject_changed||verdict==='risk'&&x.quality.open_issue_count>0||verdict===x.review.semantic_verdict)&&(issueFilter==='all'||issueFilter==='repaired'&&x.quality.targeted_repair||issueFilter==='open'&&x.quality.open_issue_count>0||issueFilter===x.quality.severity)&&`${x.id} ${x.stem} ${x.subject} ${x.topic} ${x.topic_family} ${x.microtopic} ${x.review.rationale}`.toLowerCase().includes(query.toLowerCase()))}
function clearQuestionContext(){questionContext.topic=null;questionContext.difficulty=false;questionContext.label='';issueFilter='all';difficultyQuestionBand='all';query='';verdict='all';page=0}
function cohortNotice(){let a=selectedQuestionRows();return `<div class="cohort-note"><div><strong>${a.length} questions · ${sum(a.map(q=>q.marks))} marks</strong><span>${questionContext.topic?E(questionContext.topic)+' · ':''}${questionContext.difficulty?(difficultyState.excludeMTA?'MTA excluded':'MTA included')+' · '+(difficultyState.confidence==='high'?'high-confidence ratings':'all rating confidence'):'Question-bank scope · MTA included unless a difficulty drill is active'} · bands ${difficultyState.easy}/${difficultyState.tough}</span></div><button class="button" id="clearQuestionContext">Clear question filters</button></div>`}
function issueHub(){let rows=scope(),q=rows.map(x=>QUALITY_MAP.get(x.id)),open=q.filter(x=>x.open_issue_count),repaired=rows.filter(x=>x.quality.targeted_repair);return `<div class="release-strip"><span class="release-pill">RESEARCH PREVIEW</span><p>Content repairs are tracked field by field. Source pages are authoritative. Independent expert certification and response calibration remain pending.</p><a href="RELEASE_NOTES.md" class="link">RELEASE NOTES ↗</a></div>`+metricCards([['Targeted content repairs',repaired.length,'Corrected fields · originals retained'],['Open flagged records',open.length,'Residual flags are conservatively retained'],['Source pages available',rows.length,'Official paper image in every inspector'],['Taxonomy conventions',rows.filter(x=>x.taxonomy_resolution).length,'Primary topic plus secondary context']])+panel('01','Quality control desk','Inspect a record to see its exact issue dispositions and corrections.',`<div class="quality-actions"><label>Issue queue <select id="issueFilter">${[['all','All records'],['critical','Critical flags'],['major','Major flags'],['minor','Minor flags'],['open','Any open flag'],['repaired','Targeted repairs applied'],['none','No open flagged issue']].map(([v,l])=>`<option value="${v}" ${issueFilter===v?'selected':''}>${l}</option>`).join('')}</select></label><a class="button" href="issue-register.csv" download>All issue dispositions / CSV</a><a class="button" href="content-repairs.json" download>Repair evidence / JSON</a></div><div class="quality-explainer"><p><b>130 missing-source flags resolved.</b> Existing official URLs, pages and PDF hashes now supply that evidence. These metadata fixes are separate from clean question transcription.</p><p><b>Four overlaps resolved by convention.</b> The primary label follows the minimal substantive solution operation; secondary subjects retain valid alternate context. Marks count once.</p><p><b>Open does not always mean incorrect.</b> Diagram transcription, formatting and confirmed defects are separate dispositions. A corrected field does not silently close unrelated flags.</p></div>`,'','This queue is an issue register, not a count of proven wrong questions.')}
const questionListBeforeV4=questionList;
questionList=function(audit=false){return (audit?issueHub():'')+cohortNotice()+questionListBeforeV4(false)};
inspect=function(id){const q=R.questions.find(x=>x.id===id);if(!q)return;const issue=QUALITY_MAP.get(id);let options={};try{options=JSON.parse(q.options||'{}')}catch{};$('#inspectBody').innerHTML=`<div class="overline">QUESTION EVIDENCE / ${E(id)}</div><h2 class="inspect-title">${E(q.topic)}</h2><div class="legend">${badge(q.subject)}${badge(q.type+' · '+q.marks+' marks')}${badge(q.quality.targeted_repair?'TARGETED REPAIR':'SOURCE AVAILABLE',q.quality.targeted_repair?'green':'')}${badge(q.quality.open_issue_count+' OPEN FLAGS',q.quality.open_issue_count?'amber':'green')}</div><div class="inspect-grid"><div><section class="source-reader"><div class="reader-head"><h3>Official question source</h3><a class="button" href="${E(q.source.url)}#page=${q.source.page}" target="_blank" rel="noopener">PDF · page ${q.source.page} ↗</a></div><p>Question ${q.official_number} · ${E(q.section)} · ${q.year}. The full source page may contain neighbouring questions. Open an image to zoom.</p><p>Use the official paper button above to inspect wording, equations and diagrams.</p></section><details class="canonical-text" open><summary>${q.content_repair?'Corrected searchable transcription':'Searchable supplied transcription · may contain extraction defects'}</summary><p class="inspect-stem">${E(q.stem)}</p>${Object.entries(options||{}).map(([k,v])=>`<p class="inspect-stem"><b>${E(k)}.</b> ${E(v)}</p>`).join('')}${q.probability_table?`<pre class="original-text">${E(JSON.stringify(q.probability_table,null,2))}</pre>`:''}<p class="sub">Read mathematics, diagrams and visual answer choices in the official image. These text fields are not a full accessible-transcription certification.</p></details><details class="source-answer"><summary>Reveal final answer key</summary><p><b>${E(q.reviewed_answer)}</b> · ${E(q.scoring_status)}</p><p>Supplied key: ${E(q.supplied_answer)}</p></details>${q.original_transcription?`<details class="canonical-text"><summary>Original supplied transcription / before repair</summary><p class="inspect-stem">${E(q.original_transcription.stem)}</p><pre class="original-text">${E(q.original_transcription.options)}</pre></details>`:''}</div><div>${toughInspector(q)}<div class="detail-card"><h3>TOPIC ASSIGNMENT</h3><strong>${E(q.subject)} / ${E(q.topic_family)}</strong><p>${E(q.microtopic)}</p><p>${E(q.review.rationale)}</p><p>Secondary context: ${E(q.secondary_subjects.join(', ')||'None assigned')}</p>${q.taxonomy_resolution?'<p class="mini-tag green">RESOLVED BY DECLARED CONVENTION</p><p>Primary solution operation v1 · previous ambiguity retained in the audit.</p>':''}</div>${q.content_repair?`<div class="detail-card"><h3>APPLIED CONTENT REPAIR</h3><p>${E(q.content_repair.reason)}</p><p>Fields: ${Object.keys(q.content_repair.fields||{}).map(E).join(', ')}</p><p>${E(q.content_repair.evidence.basis)}</p><ul>${q.content_repair.remaining_requirements.map(s=>`<li>${E(s)}</li>`).join('')}</ul></div>`:''}<div class="detail-card"><h3>ISSUE DISPOSITIONS</h3>${issue.dispositions.map(d=>`<div class="issue-item"><strong>${E(d.flag)}</strong><span class="mini-tag ${d.status.startsWith('open')?'amber':'green'}">${E(d.status.replaceAll('_',' '))}</span><p>${E(d.resolution||d.action)}</p></div>`).join('')||'<p>No original flags in this record. This is not independent certification.</p>'}</div><div class="detail-card"><h3>PROVENANCE & CALIBRATION</h3><p>Official source page ${q.source.page}. Visual source comparison and final key review are recorded separately in the audit.</p><p class="hash-value">SHA-256 ${E(q.source.source_sha256)}</p><p>Observed difficulty, discrimination, IRT and time distributions remain unestimated until candidate-response data is supplied.</p></div></div></div>`;$('#inspector').showModal()};
function sensitivityPanel(a){const pairs=[[25,55],[30,60],[35,65],[40,70],[45,75]];return `<details class="panel analysis-details"><summary>Threshold sensitivity / how much do labels change?</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>Easy / Tough cutoffs</th><th>Easy</th><th>Moderate</th><th>Tough</th><th>Tough mark share</th></tr></thead><tbody>${pairs.map(([e,t])=>{let easy=a.filter(q=>q.toughness.score<e),tough=a.filter(q=>q.toughness.score>=t),marks=sum(a.map(q=>q.marks));return `<tr><td>${e} / ${t}</td><td>${easy.length}</td><td>${a.length-easy.length-tough.length}</td><td>${tough.length}</td><td>${marks?F(sum(tough.map(q=>q.marks))/marks*100)+'%':'—'}</td></tr>`}).join('')}</tbody></table></div><p class="panel-content">Same ${a.length} questions and fixed scores across every row. Only labels change; cutoffs are editorial choices.</p></details>`}
function componentPanel(a){return `<details class="panel analysis-details"><summary>Component distributions / what makes the questions demanding?</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>Component</th><th>Weight</th>${[0,1,2,3,4].map(i=>`<th>Rating ${i}</th>`).join('')}<th>Mean / 4</th></tr></thead><tbody>${DIMS.map(([k,l,w])=>`<tr><td>${l}</td><td>${w}%</td>${[0,1,2,3,4].map(i=>`<td>${a.filter(q=>q.toughness.dimensions[k]===i).length}</td>`).join('')}<td>${a.length?F(mean(a.map(q=>q.toughness.dimensions[k])),2):'—'}</td></tr>`).join('')}</tbody></table></div><p class="panel-content">Each row sums to ${a.length} questions. Component ratings describe solution demands, not candidate accuracy.</p></details>`}
toughTopicGroups=function(a){const keys=[...new Set(a.map(q=>q.subject+'\u0000'+q[topicField]))];return keys.map(key=>{let[subject,topic]=key.split('\u0000'),items=a.filter(q=>q.subject===subject&&q[topicField]===topic),s=toughStats(items);return{subject,topic,items,...s,share:s.bands.Tough.n/s.n,volatility:s.sd||0}})};
const difficultyBeforeV4=difficulty;
difficulty=function(){return `<div class="release-strip"><span class="release-pill">CONTENT ESTIMATES</span><p>Scores describe solution demands for a prepared candidate. Every chart links to the same filtered questions.</p><a class="link" href="#audit">QUALITY DESK ↗</a></div><div class="granularity-control"><label>Topic detail <select id="topicGranularity"><option value="topic_family" ${topicField==='topic_family'?'selected':''}>Topic family</option><option value="topic" ${topicField==='topic'?'selected':''}>Reviewed topic</option><option value="microtopic" ${topicField==='microtopic'?'selected':''}>Microtopic</option></select></label><span>Detail level applies to topic rankings, maps and drilldowns.</span></div>`+difficultyBeforeV4().replaceAll('scored records','selected records')+sensitivityPanel(toughRows())+componentPanel(toughRows())};
function exportCurrentView(){if(view==='difficulty'){exportDifficulty();return}if(view==='responses'){download('gate-response-analysis.json',JSON.stringify({version:R.version,analysis:responseData,scope:'Imported local response dataset; global corpus filters do not apply'},null,2),'application/json');return}if(view==='inference'){download('gate-paper-inference.json',JSON.stringify({version:R.version,scope:'All eight annual papers; global filters do not apply',subject:infer,result:R.subject_stats.find(s=>s.subject===infer)},null,2),'application/json');return}const q=(view==='questions'||view==='audit')?selectedQuestionRows():scope();const data={version:R.version,view,scope:{from:+$('#from').value,to:+$('#to').value,subject:$('#subject').value,review:$('#quality').value},questionFilters:(view==='questions'||view==='audit')?{search:query,verdict,issueFilter,...questionContext,band:difficultyQuestionBand,thresholds:{easy:difficultyState.easy,tough:difficultyState.tough},excludeMTA:questionContext.difficulty&&difficultyState.excludeMTA,confidence:questionContext.difficulty?difficultyState.confidence:'all'}:null,summary:{questions:q.length,marks:sum(q.map(x=>x.marks))},questions:q.map(x=>({id:x.id,year:x.year,subject:x.subject,topic:x.topic,topic_family:x.topic_family,microtopic:x.microtopic,marks:x.marks,format:x.type,scoring_status:x.scoring_status,score:x.toughness.score,band:toughBand(x.toughness.score),quality:x.quality,source:x.source}))};download(`gate-${view}-filtered.json`,JSON.stringify(data,null,2),'application/json');toast('Exported exactly '+q.length+' matching question records.')}
$('#export').onclick=exportCurrentView;
document.addEventListener('click',e=>{const t=e.target.closest('[data-diff-topic],[data-diff-topic-year],[data-diff-drill],[data-topic-family]');if(t){e.preventDefault();e.stopImmediatePropagation();const d=t.dataset;clearQuestionContext();questionContext.difficulty=!('topicFamily'in d);questionContext.field='topicFamily'in d?'topic_family':topicField;if(d.subject)$('#subject').value=d.subject;if(d.diffDrill){$('#from').value=$('#to').value=d.diffDrill;difficultyQuestionBand=d.band}else{questionContext.topic=d.diffTopic||d.topic||d.topicFamily;if(d.diffTopicYear)$('#from').value=$('#to').value=d.diffTopicYear}questionContext.label='Linked chart cohort';location.hash='questions';render();return}if(e.target.id==='clearQuestionContext'){clearQuestionContext();render()}if(e.target.id==='reset')clearQuestionContext()},true);
document.addEventListener('change',e=>{if(e.target.id==='issueFilter'){issueFilter=e.target.value;page=0;render()}if(e.target.id==='topicGranularity'){topicField=e.target.value;render()}if(e.target.id==='questionToughnessBand'){questionContext.difficulty=true;render()}},false);
const renderBeforeV4=render;
render=function(){renderBeforeV4();document.querySelectorAll('[data-question],[data-select-subject],[data-sort],[data-scope-year],[data-diff-topic],[data-diff-topic-year],[data-diff-heat-year],[data-topic-family]').forEach(el=>{if(el.tagName!=='BUTTON'&&el.tagName!=='A'){el.tabIndex=0;el.setAttribute('role','button');el.setAttribute('aria-label',(el.textContent||'Inspect data').trim().slice(0,180))}});document.querySelectorAll('[data-nav]').forEach(el=>{if(el.dataset.nav===view)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});$('#mobileMenu').setAttribute('aria-expanded',document.body.classList.contains('menu-open')?'true':'false')};
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"]')){e.preventDefault();e.target.click()}});
document.addEventListener('click',e=>{if(e.target.closest('#mobileMenu'))$('#mobileMenu').setAttribute('aria-expanded',document.body.classList.contains('menu-open')?'true':'false')});
render();
